import React, { useState, useEffect } from "react";
import api from "../../api";
import { FaPlus } from "react-icons/fa";
import Create from "../form/penghargaan/create";
import Update from "../form/penghargaan/update";

const Penghargaan = () => {
  const [data, setData] = useState([]);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showUpdateModal, setShowUpdateModal] = useState(false);
  const [formData, setFormData] = useState({
    judul: "",
    kategori: "",
    content: "",
    gambar: null
  });
  const [loading, setLoading] = useState(false); // Tambahkan state loading

  useEffect(() => {
    api.get('/penghargaan')
      .then(response => {
        setData(response.data.artikel);
      })
      .catch(error => {
        console.error("Error fetching data:", error);
      });
  }, []);

  const handleOpenModal = () => {
    setShowModal(true);
    setFormData({
      judul: "",
      kategori: "",
      content: "",
      gambar: null
    });
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setFormData(prev => ({ ...prev, gambar: file }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true); // Set loading to true when form is being submitted

    const formDataToSend = new FormData();
    formDataToSend.append('judul', formData.judul);
    formDataToSend.append('kategori', formData.kategori);
    formDataToSend.append('content', formData.content);
    if (formData.gambar) formDataToSend.append('gambar', formData.gambar);

    api.post('/penghargaan/create', formDataToSend)
      .then(response => {
        setData([...data, response.data]);
        setShowModal(false);
        setLoading(false); // Set loading to false when request is successful
      })
      .catch(error => {
        console.error("Error submitting form:", error);
        setLoading(false); // Set loading to false in case of error
      });
  };

  const handleSubmitCreate = (formData) => {
    setLoading(true);

    const formDataToSend = new FormData();
    formDataToSend.append("name", formData.name);
    if (formData.gambar) formDataToSend.append("gambar", formData.gambar);

    api.post("/corousel/create", formDataToSend)
      .then((response) => {
        setData([...data, response.data]);
        setShowCreateModal(false);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error submitting form:", error);
        setLoading(false);
      });
  };

  const handleSubmitUpdate = (formData) => {
    setLoading(true);

    const formDataToSend = new FormData();
    formDataToSend.append("name", formData.name);
    if (formData.gambar) formDataToSend.append("gambar", formData.gambar);

    api.post(`/corousel/update/${currentData.id}`, formDataToSend)
      .then((response) => {
        const updatedData = data.map((item) =>
          item.id === currentData.id ? response.data : item
        );
        setData(updatedData);
        setShowUpdateModal(false);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error updating form:", error);
        setLoading(false);
      });
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this item?")) {
      api.delete(`/corousel/delete/${id}`)
        .then(() => {
          setData(data.filter((item) => item.id !== id));
        })
        .catch((error) => {
          console.error("Error deleting item:", error);
        });
    }
  };

  return (
    <div>
      {/* Button Create Penghargaan */}
      <button
        onClick={handleOpenModal}
        className="bg-teal-500 text-white py-2 px-4 rounded-lg mb-4 flex items-center"
      >
        <FaPlus className="inline-block mr-2 mb-1" /> Create Penghargaan
      </button>

      {/* Tampilkan tabel penghargaan */}
      <div className="grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
          <thead className="bg-teal-700 text-white">
            <tr>
              <th className="px-6 py-3 text-left font-medium">No</th>
              <th className="px-6 py-3 text-left font-medium">Judul</th>
              <th className="px-6 py-3 text-left font-medium">Kategori</th>
              <th className="px-6 py-3 text-left font-medium">Content</th>
              <th className="px-6 py-3 text-left font-medium">Action</th>
            </tr>
          </thead>
          <tbody>
            {data.length > 0 ? (
              data.map((row, index) => (
                <tr key={row.id}>
                  <td className="px-6 py-4">{index + 1}</td>
                  <td className="px-6 py-4">{row.judul}</td>
                  <td className="px-6 py-4">{row.kategori}</td>
                  <td className="px-6 py-4">{row.content}</td>
                  <td className="px-6 py-4">
                    <button
                      onClick={handleOpenModal}
                      className="bg-teal-500 text-white py-1 px-3 rounded-lg"
                    >
                      Edit
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5" className="text-center px-6 py-4 text-gray-500">
                  Tidak ada penghargaan tersedia.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Modal Form */}
      {showCreateModal && (
        <Create
          onSubmit={handleSubmitCreate}
          onClose={handleCloseModal}
          loading={loading}
        />
      )}

      {showUpdateModal && (
        <Update
          onSubmit={handleSubmitUpdate}
          onClose={handleCloseModal}
          initialData={currentData}
          loading={loading}
        />
      )}
    </div>
  );
};

export default Penghargaan;
